    Vector* vec = (Vector*)malloc(sizeof(Vector));
    TEST_ASSERT_NOT_NULL(vec);
    int init_result = init(vec, 0);
    TEST_ASSERT_EQUAL_INT(0, init_result);

    int length = len(vec);
    TEST_ASSERT_EQUAL_INT(0, length);

    helper_cleanup_vector(vec);
}

void unit_test_len_after_push(void) {
    Vector* vec = helper_create_vector(5);
    TEST_ASSERT_NOT_NULL(vec);

    int values[] = {10, 20, 30};
    int fill_result = helper_fill_vector(vec, values, 3);
    TEST_ASSERT_EQUAL_INT(0, fill_result);

    int length = len(vec);
    TEST_ASSERT_EQUAL_INT(3, length);

    helper_cleanup_vector(vec);
}

int main(void) {
    UNITY_BEGIN();
    RUN_TEST(unit_test_len_non_empty_vector);
    RUN_TEST(unit_test_len_empty_vector);
    RUN_TEST(unit_test_len_after_push);
